import java.time.*;
import java.time.format.*;
import java.util.Arrays;

sealed interface Command {
    record Add(LocalDateTime start, int minutes, String title) implements Command { }
    record Remove(String title) implements Command { }
    record Day(LocalDate date) implements Command { }
    record Free(LocalDate date, int minutes) implements Command { }
    record Summary() implements Command { }
    record Quit() implements Command { }
    record Invalid(String message) implements Command { }

    DateTimeFormatter DATE = DateTimeFormatter.ofPattern("uuuu-MM-dd").withResolverStyle(ResolverStyle.STRICT);
    DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm").withResolverStyle(ResolverStyle.STRICT);

    static Command parse(String line) {
        String[] w = line.trim().split("\\s+");
        if (w[0].isEmpty()) return new Invalid("Empty line");
        String cmd = w[0].toLowerCase();
        String[] args = Arrays.copyOfRange(w, 1, w.length);
        try {
            return switch (cmd) {
                case "add" -> args.length < 4 ? new Invalid("Usage: add <date> <time> <minutes> <title>") : add(args);
                case "remove" -> args.length == 0 ? new Invalid("Usage: remove <title>") : new Remove(String.join(" ", args));
                case "day" -> args.length != 1 ? new Invalid("Usage: day <date>") : new Day(LocalDate.parse(args[0], DATE));
                case "free" -> args.length != 2 ? new Invalid("Usage: free <date> <minutes>")
                                                : new Free(LocalDate.parse(args[0], DATE), minutes(args[1]));
                case "summary" -> new Summary();
                case "quit" -> new Quit();
                default -> new Invalid("Unknown command: " + w[0]);
            };
        } catch (DateTimeParseException e) {
            return new Invalid("Bad date or time");
        } catch (IllegalArgumentException e) {
            return new Invalid(e.getMessage());
        }
    }

    private static Command add(String[] args) {
        LocalDate date = LocalDate.parse(args[0], DATE);
        LocalTime time = LocalTime.parse(args[1], TIME);
        int minutes = minutes(args[2]);
        return new Add(LocalDateTime.of(date, time), minutes, String.join(" ", Arrays.copyOfRange(args, 3, args.length)));
    }

    private static int minutes(String text) {
        int m;
        try {
            m = Integer.parseInt(text);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Bad number");
        }
        if (m < 5 || m > 720) throw new IllegalArgumentException("Minutes must be between 5 and 720");
        return m;
    }
}

