import java.time.format.TextStyle;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Schedule schedule = new Schedule();
        loop:
        while (in.hasNextLine()) {
            Command command = Command.parse(in.nextLine());
            switch (command) {
                case Command.Add(var start, int minutes, String title) -> {
                    Event event = new Event(title, start, minutes);
                    Optional<Event> clash = schedule.firstOverlap(event);
                    if (clash.isPresent()) {
                        System.out.println("Overlaps with " + clash.get().title() + " (" + clash.get().span() + ")");
                    } else {
                        schedule.add(event);
                        System.out.println("Added: " + event.start().toLocalDate() + " " + event.span() + " " + title);
                    }
                }
                case Command.Remove(String title) -> System.out.println(
                    schedule.remove(title).map(e -> "Removed: " + e.title()).orElse("No event called " + title));
                case Command.Day(var date) -> {
                    System.out.println(date.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH) + " " + date);
                    List<Event> events = schedule.on(date);
                    if (events.isEmpty()) System.out.println("  Nothing planned.");
                    for (Event e : events) System.out.println("  " + e.span() + " " + e.title());
                }
                case Command.Free(var date, int minutes) -> System.out.println(
                    schedule.freeSlot(date, minutes).map(s -> "Free: " + s)
                            .orElse("No free slot of " + minutes + " minutes on " + date));
                case Command.Summary s -> {
                    if (schedule.count() == 0) {
                        System.out.println("No events.");
                    } else {
                        int total = schedule.totalMinutes();
                        System.out.println(schedule.count() + (schedule.count() == 1 ? " event, " : " events, ")
                            + total / 60 + "h " + total % 60 + "m planned");
                        var busiest = schedule.busiestDay();
                        System.out.println("Busiest day: " + busiest.getKey() + " (" + busiest.getValue()
                            + (busiest.getValue() == 1 ? " event)" : " events)"));
                    }
                }
                case Command.Invalid(String message) -> System.out.println(message);
                case Command.Quit q -> {
                    break loop;
                }
            }
        }
        System.out.println("Bye.");
    }
}

