import java.time.*;

record Event(String title, LocalDateTime start, int minutes) {
    LocalDateTime end() { return start.plusMinutes(minutes); }

    boolean overlaps(LocalDateTime from, LocalDateTime to) {
        return start.isBefore(to) && from.isBefore(end());
    }

    boolean overlaps(Event other) { return overlaps(other.start, other.end()); }

    String span() { return start.toLocalTime() + "-" + end().toLocalTime(); }
}

