import java.time.*;
import java.util.*;

class Schedule {
    private static final LocalTime DAY_START = LocalTime.of(8, 0), DAY_END = LocalTime.of(18, 0);
    private static final Comparator<Event> BY_START = Comparator.comparing(Event::start);
    private final List<Event> events = new ArrayList<>();

    Optional<Event> firstOverlap(Event e) {
        return events.stream().filter(e::overlaps).findFirst();
    }

    void add(Event e) {
        if (firstOverlap(e).isPresent()) throw new IllegalArgumentException("overlap");
        events.add(e);
        events.sort(BY_START);
    }

    Optional<Event> remove(String title) {
        for (Iterator<Event> it = events.iterator(); it.hasNext(); ) {
            Event e = it.next();
            if (e.title().equalsIgnoreCase(title)) {
                it.remove();
                return Optional.of(e);
            }
        }
        return Optional.empty();
    }

    List<Event> on(LocalDate date) {
        return events.stream().filter(e -> e.start().toLocalDate().equals(date)).toList();
    }

    Optional<String> freeSlot(LocalDate date, int minutes) {
        LocalDateTime from = date.atTime(DAY_START), to = date.atTime(DAY_END);
        LocalDateTime cursor = from;
        for (Event e : events) {
            if (!e.overlaps(from, to)) continue;
            if (Duration.between(cursor, e.start()).toMinutes() >= minutes) {
                return Optional.of(cursor.toLocalTime() + "-" + e.start().toLocalTime());
            }
            if (e.end().isAfter(cursor)) cursor = e.end();
        }
        if (cursor.isBefore(to) && Duration.between(cursor, to).toMinutes() >= minutes) {
            return Optional.of(cursor.toLocalTime() + "-" + DAY_END);
        }
        return Optional.empty();
    }

    int count() { return events.size(); }

    int totalMinutes() { return events.stream().mapToInt(Event::minutes).sum(); }

    Map.Entry<LocalDate, Integer> busiestDay() {
        Map<LocalDate, Integer> perDay = new TreeMap<>();
        for (Event e : events) perDay.merge(e.start().toLocalDate(), 1, Integer::sum);
        Map.Entry<LocalDate, Integer> best = null;
        for (Map.Entry<LocalDate, Integer> entry : perDay.entrySet()) {
            if (best == null || entry.getValue() > best.getValue()) best = entry;
        }
        return best;
    }
}

